-- Collection-Bound: Regional Championship Europe (Stuttgart) additions, 117 items.
-- 53 Overnumbered Foil Plated Legends (draft), 30 Prize Wall Plated Legends,
-- 16 Double-Tall Borderless Battlefields, RC exclusives, Nation Clash Champion
-- Ekko, Attendee Seraphine, Judge Kai'Sa, competitor jacket, Five-Game Challenge
-- prizes and the 6 Radiance Nexus Night alternate-art runes.
-- Run AFTER the GitHub PR is merged. Safe to run more than once: anything whose
-- name + language is already in the catalog is skipped. Only ADDS rows (plus
-- one small fix: Ziggs' Plated Legend gets its Radiance set code).
update promo_items set data = data || '{"se":"RAD"}'::jsonb
 where data->>'nm' = 'Ziggs - Hexplosives Expert (RC Stuttgart Plated Legend)' and coalesce(data->>'se','') = '';
