base as (select coalesce(max(r), 0) as mr from promo_items),
casing as (select
  coalesce((select data->>'st'  from promo_items where upper(data->>'st')  = 'NEED' limit 1), 'NEED') as st),
fresh as (
  select i.ord, i.data from incoming i
  where not exists (select 1 from promo_items p
    where lower(trim(p.data->>'nm')) = lower(trim(i.data->>'nm')) and coalesce(p.data->>'la','') = coalesce(i.data->>'la',''))
),
numbered as (select data, (select mr from base) + row_number() over (order by ord) as nr from fresh)
insert into promo_items (id, r, data)
select 'item-' || n.nr, n.nr, n.data || jsonb_build_object('r', n.nr, 'id', 'item-' || n.nr, 'st', c.st)
from numbered n cross join casing c
returning id, data->>'nm' as name;
